$ErrorActionPreference = 'Stop'
$markdown = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'research.md') -Raw
$body = $markdown -replace '(?s)\A---\r?\n.*?\r?\n---\r?\n', ''
$content = (ConvertFrom-Markdown -InputObject $body).Html
$style = 'body{margin:0;background:#f4f7fb;color:#172033;font-family:Segoe UI,Microsoft JhengHei,sans-serif;line-height:1.9}main{max-width:1080px;margin:30px auto;padding:38px;background:white;border-radius:18px}h1,h2{line-height:1.45}h1{font-size:2.4rem}h2{margin-top:2.4em;border-bottom:1px solid #dde4ef;padding-bottom:10px}a{color:#1756b9;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:.93rem;display:block;overflow-x:auto}td,th{border:1px solid #dce3ee;padding:12px;text-align:left;min-width:130px}th{background:#eef4fc}blockquote{margin:24px 0;background:#fff5de;border-left:4px solid #c18618;padding:12px 20px;color:#684d21}nav{font-size:.9rem}li{margin:9px 0}@media(max-width:700px){main{margin:0;padding:20px;border-radius:0}h1{font-size:1.9rem}}@media print{body{background:white}main{margin:0;padding:0;max-width:none}h2{break-after:avoid}tr{break-inside:avoid}}'
$html = '<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="MedAI、法律偵探／TLR、Elora 與 Kbag 的 AI coding 案例研究：開發證據、工作流、成果與限制。"><title>AI Coding 民間案例研究</title><style>' + $style + '</style></head><body><main><nav><a href="../../../../index.html">知識庫首頁</a> · <a href="../../index.html">AI Coding</a> · <a href="research.md">Markdown 原文</a></nav>' + $content + '<footer>研究建立與來源核對：2026-10-21 · 公開資料研究，部分開發證據待補。以 research.md 維護，build.ps1 產生閱讀頁。</footer></main></body></html>'
$html | Set-Content -LiteralPath (Join-Path $PSScriptRoot 'index.html') -Encoding utf8
